function p = HS13()
% HS13: generated by bench/corpus/generate.py from the SymPy definition. Do not edit.
% source: Hock & Schittkowski 1981; MFCQ fails at the solution
p.name = 'HS13'; p.family = 'hs'; p.n = 2; p.m = 1;
p.x0 = [-2.0; -2.0];
p.xl = [0.0; 0.0]; p.xu = [Inf; Inf];
p.cl = [0.0]; p.cu = [Inf];
p.ref_f = 1.0;
p.checksum = '3d2cbd86decf4d65';
p.f = @HS13_f; p.grad = @HS13_g; p.c = @HS13_c; p.jac = @HS13_J;
end

function f = HS13_f(x)
f = x(2).^2 + (x(1) - 2).^2;
end

function g = HS13_g(x)
g = zeros(2, 1);
g(1) = 2*x(1) - 4;
g(2) = 2*x(2);
end

function c = HS13_c(x)
c = zeros(1, 1);
c(1) = -x(2) + (1 - x(1)).^3;
end

function J = HS13_J(x)
J = zeros(1, 2);
J(1, 1) = -3*(1 - x(1)).^2;
J(1, 2) = -1;
end
